typedef unsigned short U16;

char expr[1000005];
int posi;
U16 val[4];          // bitsets for a,b,c,d over all 10000 passwords
int target[4];       // given password digits

// Grammar:
// expr := xor
// xor  := and {'^' and}
// and  := or  {'*' or}
// or   := primary {'+' primary}
// primary := 'a'|'b'|'c'|'d'|'(' expr ')'
//
// precedence: + > * > ^

U16 parse_expr();

void skip_spaces() {
    while (expr[posi] && isspace((unsigned char)expr[posi])) posi++;
}

U16 parse_primary() {
    skip_spaces();
    char c = expr[posi];
    if (c == '(') {
        posi++;
        U16 r = parse_expr();
        skip_spaces();
        if (expr[posi] == ')') posi++;
        return r;
    }
    posi++;
    if (c == 'a') return val[0];
    if (c == 'b') return val[1];
    if (c == 'c') return val[2];
    return val[3]; // 'd'
}

U16 parse_or() {
    U16 r = parse_primary();
    while (1) {
        skip_spaces();
        if (expr[posi] != '+') break;
        posi++;
        r = r | parse_primary();
    }
    return r;
}

U16 parse_and() {
    U16 r = parse_or();
    while (1) {
        skip_spaces();
        if (expr[posi] != '*') break;
        posi++;
        r = r & parse_or();
    }
    return r;
}

U16 parse_expr() {
    U16 r = parse_and();
    while (1) {
        skip_spaces();
        if (expr[posi] != '^') break;
        posi++;
        r = r ^ parse_and();
    }
    return r;
}

