#include <bits/stdc++.h>
using namespace std;

// Memoization for hash function evaluation
map<string, int> memo;

int evaluate(const string& s, const vector<int>& pw) {
    if (memo.count(s)) return memo[s];
    // If it's a single digit reference
    if (s.size() == 1 && s[0] >= 'a' && s[0] <= 'd') {
        return pw[s[0] - 'a'];
    }
    // Find the main operator (lowest precedence)
    // precedence: + lowest, then ^, then *
    int depth = 0;
    int opPos = -1;
    int opType = 0; // 0 none, 1 '+', 2 '^', 3 '*'
    for (int i = (int)s.size()-1; i >= 0; i--) {
        if (s[i] == '(') depth++;
        else if (s[i] == ')') depth--;
        else if (depth == 0) {
            if (s[i] == '+') {
                opPos = i;
                opType = 1;
                break; // lowest precedence, take the last one
            } else if (s[i] == '^' && opType == 0) {
                opPos = i;
                opType = 2;
            } else if (s[i] == '*' && opType == 0) {
                opPos = i;
                opType = 3;
            }
        }
    }
    if (opPos != -1) {
        string left = s.substr(0, opPos);
        string right = s.substr(opPos+1);
        int lv = evaluate(left, pw);
        int rv = evaluate(right, pw);
        int res;
        if (opType == 1) res = lv | rv;
        else if (opType == 2) res = lv ^ rv;
        else res = lv & rv;
        memo[s] = res;
        return res;
    }
    // Otherwise it's a parenthesized expression
    if (s.front() == '(' && s.back() == ')') {
        string inner = s.substr(1, s.size()-2);
        int res = evaluate(inner, pw);
        memo[s] = res;
        return res;
    }
    // Should not happen
    return 0;
}

