#include <bits/stdc++.h>
using namespace std;

struct Node {
    char op;              // 'a','b','c','d','+','*','^'
    int l = -1, r = -1;   // children for operators
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string expr, pass;
    while (cin >> expr >> pass) {
        // Parse prefix expression recursively
        vector<Node> nodes;
        int pos = 0;

        function<int()> parse = [&]() -> int {
            char ch = expr[pos++];
            Node nd;
            nd.op = ch;
            int id = (int)nodes.size();
            nodes.push_back(nd);

            if (ch == '+' || ch == '*' || ch == '^') {
                int L = parse();
                int R = parse();
                nodes[id].l = L;
                nodes[id].r = R;
            }
            return id;
        };

        int root = parse();
        int n = (int)nodes.size();

        // For every node, compute 16-bit truth table over all 4-bit passwords.
        // Bit k corresponds to password bits:
        // a = bit3, b = bit2, c = bit1, d = bit0 of k (or any fixed consistent order).
        vector<uint16_t> val(n, 0);

        function<uint16_t(int)> build = [&](int u) -> uint16_t {
            char op = nodes[u].op;
            if (op == 'a' || op == 'b' || op == 'c' || op == 'd') {
                int idx = op - 'a'; // 0..3
                uint16_t mask = 0;
                for (int s = 0; s < 16; ++s) {
                    int bit = (s >> (3 - idx)) & 1; // a,b,c,d = bits 3,2,1,0
                    if (bit) mask |= (uint16_t(1) << s);
                }
                val[u] = mask;
            } else {
                uint16_t A = build(nodes[u].l);
                uint16_t B = build(nodes[u].r);
                if (op == '+') val[u] = A | B;
                else if (op == '*') val[u] = A & B;
                else val[u] = A ^ B; // '^'
            }
            return val[u];
        };

        uint16_t table = build(root);

        int given =
            ((pass[0] - '0') << 3) |
            ((pass[1] - '0') << 2) |
            ((pass[2] - '0') << 1) |
            ((pass[3] - '0'));

        int hashValue = (table >> given) & 1;

        int cnt = 0;
        for (int s = 0; s < 16; ++s) {
            if (((table >> s) & 1) == hashValue) ++cnt;
        }

        cout << hashValue << ' ' << cnt << '\n';
    }

    return 0;
}

