public class Main {

    static Map<Character, Integer> varMap;
    static String expr;
    static int idx;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.isEmpty()) continue;

            // Split into hash function and password
            String[] parts = line.split(" ");
            if (parts.length != 2) continue;

            String hashFunc = parts[0];
            String password = parts[1];

            // Build variable mapping for this dataset
            varMap = new HashMap<>();
            for (int i = 0; i < 4; i++) {
                varMap.put((char)('a' + i), password.charAt(i) - '0');
            }

            // Parse and evaluate expression
            expr = hashFunc;
            idx = 0;
            int hashValue = parseExpr();

            // Count number of passwords (0000-9999) that give same hash
            int count = 0;
            for (int p = 0; p <= 9999; p++) {
                String pwd = String.format("%04d", p);
                Map<Character, Integer> testMap = new HashMap<>();
                for (int i = 0; i < 4; i++) {
                    testMap.put((char)('a' + i), pwd.charAt(i) - '0');
                }

                // Evaluate with test password
                varMap = testMap;
                idx = 0;
                int testHash = parseExpr();
                if (testHash == hashValue) {
                    count++;
                }
            }

            System.out.println(hashValue + " " + count);
        }
        sc.close();
    }

    // Expression parser for bitwise operators: + (OR), * (AND), ^ (XOR)
    // Precedence: * (AND) highest, then ^ (XOR), then + (OR) lowest
    // We parse with two levels: term (for AND) and expr (for OR and XOR)

    static int parseExpr() {
        int val = parseTerm();
        while (idx < expr.length() && (expr.charAt(idx) == '+' || expr.charAt(idx) == '^')) {
            char op = expr.charAt(idx);
            idx++;
            int right = parseTerm();
            if (op == '+') {
                val = val | right;
            } else { // '^'
                val = val ^ right;
            }
        }
        return val;
    }

    static int parseTerm() {
        int val = parseFactor();
        while (idx < expr.length() && expr.charAt(idx) == '*') {
            idx++;
            int right = parseFactor();
            val = val & right;
        }
        return val;
    }

    static int parseFactor() {
        if (idx >= expr.length()) return 0;
        char c = expr.charAt(idx);
        if (c == '(') {
            idx++; // skip '('
            int val = parseExpr();
            idx++; // skip ')'
            return val;
        } else if (c >= 'a' && c <= 'd') {
            idx++;
            return varMap.get(c);
        } else {
            // Should not happen for valid input
            return 0;
        }
    }
}

