public class Main {
    static String expr;
    static int pos;
    static int[] digits = new int[4]; // a, b, c, d

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.isEmpty()) continue;
            // line contains the hash function
            // next line contains the password
            if (!sc.hasNextLine()) break;
            String passLine = sc.nextLine().trim();
            if (passLine.isEmpty()) continue;

            // Parse password
            int[] pass = new int[4];
            for (int i = 0; i < 4; i++) {
                pass[i] = passLine.charAt(i) - '0';
            }

            // Evaluate hash for given password
            int targetHash = evaluate(line, pass);

            // Count passwords with same hash
            int count = 0;
            for (int p = 0; p < 10000; p++) {
                int[] d = new int[4];
                d[0] = p / 1000;
                d[1] = (p / 100) % 10;
                d[2] = (p / 10) % 10;
                d[3] = p % 10;
                if (evaluate(line, d) == targetHash) {
                    count++;
                }
            }

            System.out.println(targetHash + " " + count);
        }
    }

    static int evaluate(String expression, int[] d) {
        expr = expression;
        pos = 0;
        digits = d;
        return parseExpr();
    }

    static int parseExpr() {
        if (pos >= expr.length()) return 0;
        char c = expr.charAt(pos);
        if (c == 'a') { pos++; return digits[0]; }
        if (c == 'b') { pos++; return digits[1]; }
        if (c == 'c') { pos++; return digits[2]; }
        if (c == 'd') { pos++; return digits[3]; }
        if (c == '(') {
            pos++; // consume '('
            int left = parseExpr();
            char op = expr.charAt(pos);
            pos++; // consume operator
            int right = parseExpr();
            pos++; // consume ')'
            if (op == '+') return left | right;
            if (op == '*') return left & right;
            if (op == '^') return left ^ right;
        }
        return 0;
    }
}

