public class Main {
    // Fast scanner for token-based input
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }

    static class Node {
        char op; // 'a','b','c','d','+','*','^'
        Node left, right;
        int[] table; // size 16, value for all 4-bit assignments

        Node(char op) {
            this.op = op;
        }

        Node(char op, Node left, Node right) {
            this.op = op;
            this.left = left;
            this.right = right;
        }
    }

    static String expr;
    static int pos;

    // Parse prefix expression:
    // variable: a b c d
    // operator: + * ^ followed by two expressions
    static Node parse() {
        char ch = expr.charAt(pos++);
        if (ch == 'a' || ch == 'b' || ch == 'c' || ch == 'd') {
            return new Node(ch);
        } else {
            Node l = parse();
            Node r = parse();
            return new Node(ch, l, r);
        }
    }

    static void buildTable(Node node) {
        node.table = new int[16];
        if (node.op >= 'a' && node.op <= 'd') {
            int bit = node.op - 'a';
            for (int mask = 0; mask < 16; mask++) {
                node.table[mask] = (mask >> bit) & 1;
            }
            return;
        }

        buildTable(node.left);
        buildTable(node.right);

        for (int mask = 0; mask < 16; mask++) {
            int x = node.left.table[mask];
            int y = node.right.table[mask];
            if (node.op == '+') node.table[mask] = x | y;
            else if (node.op == '*') node.table[mask] = x & y;
            else node.table[mask] = x ^ y;
        }
    }

    static int digitParity(int d) {
        // digit is interpreted as a 4-bit value; hash variables are its bits
        return d;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            String s = fs.next();
            if (s == null) break;
            if (s.equals(".")) break; // common sentinel for this problem

            String password = fs.next();
            if (password == null) break;

            expr = s;
            pos = 0;
            Node root = parse();
            buildTable(root);

            int mask = 0;
            for (int i = 0; i < 4; i++) {
                int d = password.charAt(i) - '0';
                if ((d & 1) != 0) mask |= (1 << i);
            }

            int hashValue = root.table[mask];

            int count = 0;
            for (int p = 0; p < 10000; p++) {
                int m = 0;
                int x = p;
                for (int i = 0; i < 4; i++) {
                    int d = x % 10;
                    x /= 10;
                    if ((d & 1) != 0) m |= (1 << i);
                }
                if (root.table[m] == hashValue) count++;
            }

            out.append(hashValue).append(' ').append(count).append('\n');
        }

        System.out.print(out.toString());
    }
}

import sys

# Parse expression:
# expr := term (('+' | '^') term)*
# term := factor ('*' factor)*
# factor := letter | '(' expr ')'
# Precedence: * > +,^   and +,^ are left-associative on same level.

class Parser:
    def __init__(self, s):
        self.s = s
        self.i = 0
        self.n = len(s)

    def peek(self):
        return self.s[self.i] if self.i < self.n else ''

    def get(self):
        ch = self.s[self.i]
        self.i += 1
        return ch

    def parse(self):
        node = self.parse_expr()
        return node

    def parse_expr(self):
        node = self.parse_term()
        while self.i < self.n and self.peek() in '+^':
            op = self.get()
            rhs = self.parse_term()
            node = (op, node, rhs)
        return node

    def parse_term(self):
        node = self.parse_factor()
        while self.i < self.n and self.peek() == '*':
            self.get()
            rhs = self.parse_factor()
            node = ('*', node, rhs)
        return node

    def parse_factor(self):
        ch = self.peek()
        if ch in 'abcd':
            self.get()
            return ch
        elif ch == '(':
            self.get()
            node = self.parse_expr()
            if self.peek() == ')':
                self.get()
            return node
        else:
            # Should not happen for valid input
            return None


def eval_node(node, vals):
    if isinstance(node, str):
        idx = ord(node) - ord('a')
        return vals[idx]
    op, l, r = node
    x = eval_node(l, vals)
    y = eval_node(r, vals)
    if op == '+':
        return x | y
    if op == '*':
        return x & y
    return x ^ y


def main():
    data = [line.strip() for line in sys.stdin if line.strip()]
    out = []

    # Input is multiple datasets: expression then password.
    # Stop if incomplete trailing line exists.
    for k in range(0, len(data) - 1, 2):
        expr = data[k]
        pwd = data[k + 1]

        parser = Parser(expr)
        tree = parser.parse()

        vals = [int(c) for c in pwd]
        h = eval_node(tree, vals)

        cnt = 0
        for a in range(10):
            for b in range(10):
                for c in range(10):
                    for d in range(10):
                        if eval_node(tree, (a, b, c, d)) == h:
                            cnt += 1

        out.append(f"{h} {cnt}")

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
